(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.012-t*0.18)*15;
  const w1y = Math.cos(y*0.018-t*0.22)*20 + Math.sin(x*0.014+t*0.3)*15;
  const w2x = Math.sin(w1x*0.03+y*0.008+t*0.15)*8;
  const w2y = Math.cos(w1y*0.03+x*0.008-t*0.12)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110,80+Math.cos(t*0.35)*55,0.075,2.1,1.0],
    [320+Math.cos(t*0.45)*110,160+Math.sin(t*0.6)*55,0.09,1.8,0.9],
    [240+Math.sin(t*0.28+2)*150,120+Math.cos(t*0.42+1)*95,0.055,2.4,1.1],
    [100+Math.cos(t*0.7+1)*90,180+Math.sin(t*0.5+3)*70,0.11,1.4,0.8],
    [380+Math.sin(t*0.38+4)*95,50+Math.cos(t*0.75+2)*75,0.065,2.7,1.0],
    [240+Math.cos(t*0.32+5)*130,200+Math.sin(t*0.48)*85,0.085,2.0,0.95],
    [60+Math.sin(t*0.55+3)*70,40+Math.cos(t*0.4+4)*50,0.1,1.6,0.85],
    [420+Math.cos(t*0.6+2)*60,220+Math.sin(t*0.35+5)*50,0.07,2.2,1.05]
  ];
  let aS=0,iS=0,harm=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    harm+=Math.sin(d*f*1.5-t*sp*0.8+2.0)*w*0.3;
  }
  const n=src.length,act=aS/n,inh=iS/n;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*0.95))/2;
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const bg3=Math.sin(sx*0.06+t*0.5)*Math.sin(sy*0.06-t*0.4)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const r1=Math.tanh((act-inh*0.65+bg*0.25+spiral)*2.0);
  const r2=Math.tanh((act*0.8-inh*0.8+harm+bg*0.15)*1.8);
  const reaction=(r1+r2)*0.5;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4)*1.4)*0.25;
  const fine=Math.sin(sx*0.25+t*0.3)*Math.sin(sy*0.22-t*0.25)*0.08;
  const blend=reaction*0.7+cell*0.2+fine*0.1;
  const v=blend*0.5+0.5;
  const vig=1.0-Math.pow(dist/280,2.5)*0.3;
  const glow=Math.max(0,Math.abs(reaction)-0.5)*0.6;
  const pal=[[5,12,55],[12,45,95],[18,85,120],[25,130,130],[60,165,120],[150,190,80],[220,195,60],[235,155,65],[220,100,70],[185,65,75],[130,40,80],[70,25,65],[30,15,55],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=(0.82+Math.sin(reaction*Math.PI)*0.18)*vig;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const gm=1.0+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*gm)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*gm)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*gm)|0
  ];
}
